"""
experiments/21_load/load_fc.py
Campus-load forecaster for hard mode (rules: docs/NEW_RULES.md).

    fc = LoadFC(fit_df)                       # fit_df: hourly table with a `load_kw` column (NaN allowed)
    fc.predict_load(obs, hist, H)             # kW for the hour being decided (index 0) and the next H-1
    fc.predict_load_quantiles(obs, hist, qs)  # quantiles of the hour being decided

How it works
  * It keeps a table {hour -> load} made of the fit rows plus every reading revealed by `obs`
    during the run, so "same hour yesterday / last week" can be looked up by timestamp even in
    the first hours of a test week (the days before a test week are train days).
  * Regime logic: the meter is not polled between 22:00 and 06:00, so hours 23, 0..5 repeat the
    22:00 value -> persistence is exact there. A reading of ~0 kW is a telemetry fault and persists.
    A timestamp jump (previous obs is not the previous hour) means the "last reading" in obs is
    stale: the previous hour is then looked up in the table, or declared unknown.
  * Hours 06..22: a small LightGBM predicts the change from the last reading.
  * Later hours: reference profile (mean of the last same-type days at that hour) plus the
    current anomaly, fading with the horizon; frozen night hours copy the 22:00 forecast.
    On weekdays the reference is a blend of the weekday and the Sunday reference; the blend
    weight ("holiday index" lam) is estimated from today's readings and carried to the next
    weekdays, so a closure week is followed after a few hours instead of being forecast as normal.
  * Quantiles of the current hour: forecast + out-of-fold residual quantiles by (hour, day type).

Runtime imports: numpy, pandas, lightgbm only.
"""
import numpy as np
lgb = None

NS_H = 3_600_000_000_000
FROZEN = frozenset((23, 0, 1, 2, 3, 4, 5))
FAULT_KW = 50.0
NAN = float("nan")

FEATS = ["hour", "dow", "etype", "L1", "d1", "d2", "dy", "dw", "L1_y", "L1_w", "dS", "aS",
         "temp", "irr", "dy_next", "yg", "wg", "sg", "a3", "a6", "doy", "d48", "rS", "yS",
         "dtemp1", "dtemp24", "dS_next", "lam_t", "lam_p", "dS_mix", "sg_mix", "lam_n"]
COLS_V1 = FEATS[:15]
COLS_V2 = [c for c in FEATS[:29] if c != "doy"]
COLS_V3 = [c for c in FEATS if c != "doy"]
IDX_DSMIX = FEATS.index("dS_mix")
IDX_SGMIX = FEATS.index("sg_mix")
IDX_LAMN = FEATS.index("lam_n")


def hidx(ts) -> int:
    """Hours since 1970-01-01 (naive local time, as in the data)."""
    return int(ts.value // NS_H)


def etype(i: int) -> int:
    """Day type of the 'meter day' (06:00 -> 05:59, because hours 0..5 repeat the previous
    evening): 0 = Mon-Fri, 1 = Saturday, 2 = Sunday."""
    dow = ((i - 6) // 24 + 3) % 7
    return 0 if dow < 5 else dow - 4


def day0(i: int) -> int:
    """Hour index of the 06:00 that starts the meter day containing hour i."""
    return i - ((i - 6) % 24)


class LoadFC:
    def __init__(self, fit_df=None, phi=0.9, rho=0.6, kappa=9e4, mix=True, n_ref=(3, 2, 2),
                 gbm_params=None, n_trees=300, oof=True, use_model=True, cols=None, base_mix=False,
                 hol_blend=0.0):
        self.hol_blend = hol_blend               # pull hour 0 towards the holiday-aware reference when the index is high
        self.base_mix = base_mix                 # model target = change minus the holiday-aware reference change
        self.phi = phi                           # per-hour fade of the current anomaly (later hours)
        self.rho = rho                           # carry-over of the holiday index to the next weekday
        self.kappa = kappa                       # shrinkage of today's holiday index towards the carried one
        self.mix = mix                           # use the holiday index for later hours
        self.n_ref = n_ref                       # reference days per type (weekday, Sat, Sun)
        self.n_trees = n_trees
        self.use_model = use_model
        self.oof = oof
        self.cols = list(cols) if cols is not None else list(COLS_V2)
        self.ci = [FEATS.index(c) for c in self.cols]
        self.gbm_params = dict(objective="huber", alpha=60.0, learning_rate=0.04, num_leaves=15,
                               min_data_in_leaf=20, feature_fraction=0.7, bagging_fraction=0.8,
                               bagging_freq=1, lambda_l2=1.0, verbose=-1, num_threads=1, seed=0)
        if gbm_params:
            self.gbm_params.update(gbm_params)
        self.base = {}            # hour -> load (fit rows)
        self.tbase = {}           # hour -> ambient temperature reading (fit rows)
        self.model = None
        self.reset()
        if fit_df is not None:
            self.fit(fit_df)

    # ------------------------------------------------------------------ run-time state
    def reset(self):
        self.tab = dict(self.base)
        self.ttab = dict(self.tbase)
        self._sc = {}             # cache of reference values
        self._dr = {}             # cache of per-day (weekday ref, Sunday ref) for hours 06..22
        self._lp = {}             # cache of the previous weekday's holiday index
        self._cur = None          # hour index of the current step
        self._prev = None         # hour index of the previous step of the run
        self._l1 = NAN            # load of hour (cur - 1) if known
        self._cache = None

    # ------------------------------------------------------------------ reference profile
    def _S(self, j: int, known: int, t: int = -1) -> float:
        """Reference load for hour j: mean of the most recent days of type t (default: the type
        of j) at the same hour, using only hours <= known. Falls back to the global profile."""
        if t < 0:
            t = etype(j)
        m0 = -((known - j) // 24)                 # smallest m with j - 24 m <= known
        if m0 < 1:
            m0 = 1
        key = (j, t, m0)
        v = self._sc.get(key)
        if v is not None:
            return v
        need = self.n_ref[t]
        tab = self.tab
        s, n = 0.0, 0
        for m in range(m0, m0 + 28):
            jj = j - 24 * m
            if etype(jj) != t:
                continue
            x = tab.get(jj)
            if x is not None:
                s += x
                n += 1
                if n == need:
                    break
        v = s / n if n else self.prof[t][j % 24]
        self._sc[key] = v
        return v

    def _dayref(self, d0: int):
        r = self._dr.get(d0)
        if r is None:
            S = self._S
            r = ([S(d0 + k, d0 - 1, 0) for k in range(17)], [S(d0 + k, d0 - 1, 2) for k in range(17)])
            self._dr[d0] = r
        return r

    def _lam_parts(self, d0: int, known: int):
        """Least-squares weight of the Sunday reference in the readings of meter day d0 (hours
        06..22 up to `known`): returns (num, den, n) with lam = num / den."""
        swd, ssu = self._dayref(d0)
        g = self.tab.get
        num = den = 0.0
        n = 0
        for k in range(min(known - d0, 16) + 1):
            v = g(d0 + k)
            if v is None:
                continue
            dd = swd[k] - ssu[k]
            num += (swd[k] - v) * dd
            den += dd * dd
            n += 1
        return num, den, n

    def _lam_prev(self, d0: int) -> float:
        """Holiday index of the last weekday before meter day d0 (NaN if unknown)."""
        v = self._lp.get(d0)
        if v is not None:
            return v
        v = NAN
        for m in range(1, 5):
            dp = d0 - 24 * m
            if etype(dp) != 0:
                continue
            num, den, n = self._lam_parts(dp, dp + 16)
            if n >= 8 and den > 1e4 * n:
                v = min(max(num / den, -1.5, ), 1.3)
            break
        self._lp[d0] = v
        return v

    def _lam_now(self, i: int):
        """(holiday index to use from hour i on, meter-day start it refers to)."""
        d0 = day0(i)
        lp = self._lam_prev(d0)
        prior = self.rho * lp if lp == lp else 0.0
        if etype(i) != 0:
            return (lp if lp == lp else 0.0), d0 - 24      # weekend: carry the last weekday's index
        num, den, n = self._lam_parts(d0, i - 1)
        lam = (num + self.kappa * prior) / (den + self.kappa)
        return min(max(lam, -1.5), 1.3), d0

    # ------------------------------------------------------------------ features of the hour-0 model
    def _features(self, i: int, l1: float, temp: float, irr: float):
        g = self.tab.get
        S = self._S
        l2 = g(i - 2, NAN)
        l3 = g(i - 3, NAN)
        l24, l25, l23 = g(i - 24, NAN), g(i - 25, NAN), g(i - 23, NAN)
        l168, l169 = g(i - 168, NAN), g(i - 169, NAN)
        s0 = S(i, i - 1)
        s1 = S(i - 1, i - 2)
        h = i % 24
        a1 = l1 - s1
        a2 = l2 - S(i - 2, i - 3) if l2 == l2 else NAN
        a3 = l3 - S(i - 3, i - 4) if l3 == l3 else NAN
        am = [a for a in (a1, a2, a3) if a == a]
        a3m = sum(am) / len(am) if am else NAN
        d0 = day0(i)
        if h > 6:
            l6 = g(d0, NAN)
            a6 = l6 - S(d0, d0 - 1) if l6 == l6 else NAN
        else:
            a6 = NAN
        lam_t = NAN
        if etype(i) == 0 and i - 1 >= d0:
            num, den, n = self._lam_parts(d0, i - 1)
            if den > 1e4 * n > 0:
                lam_t = num / den
        lam_n = 0.0
        r0, r1 = s0, s1
        if etype(i) == 0:
            lam_n = self._lam_now(i)[0]
            r0 = s0 - lam_n * (s0 - S(i, i - 1, 2))
            if h > 6:
                r1 = s1 - lam_n * (s1 - S(i - 1, i - 2, 2))
        tg = self.ttab.get
        return [h, (i // 24 + 3) % 7, etype(i), l1, l1 - l2, l2 - l3, l24 - l25, l168 - l169,
                l1 - l25, l1 - l169, s0 - s1, a1, temp, irr, l23 - l24,
                l24 - l1, l168 - l1, s0 - l1, a3m, a6, (i // 24) % 365.25, g(i - 48, NAN) - g(i - 49, NAN),
                l1 / s1 if s1 > 0 else NAN, l24 - s0,
                temp - tg(i - 2, NAN), temp - tg(i - 25, NAN), S(i + 1, i - 1) - s0,
                lam_t, self._lam_prev(d0), r0 - r1, r0 - l1, lam_n], s0

    # ------------------------------------------------------------------ fit

    # ------------------------------------------------------------------ packaging

    @classmethod
    def from_state(cls, st: dict):
        fc = cls(None, **st["params"])
        fc.base, fc.tbase, fc.prof = st["base"], st["tbase"], st["prof"]
        fc.res, fc.res_cold = st["res"], st["res_cold"]
        fc.model = lgb.Booster(model_str=st["model"]) if st["model"] else None
        fc.use_model = fc.model is not None
        fc.reset()
        return fc

    def _sync(self, obs, hist):
        i = hidx(obs["timestamp"])
        if i == self._cur:
            return i
        if self._cur is not None and (i < self._cur or (hist is not None and len(hist) == 1)):
            self.reset()                                   # a new run with the same instance
        nd = obs["noves_dades_5min"]
        last = float(nd["ultim_consum_kw"])
        prev = self._cur
        self._prev, self._cur, self._cache = prev, i, None
        if prev is not None:
            if last >= FAULT_KW:
                self.tab[prev] = last                      # the reading belongs to the previous row
            else:
                self.tab.pop(prev, None)
            tv = nd.get("temp_ambient_c")
            if tv is not None and tv == tv:
                self.ttab[prev] = float(tv)
        if prev is not None and i - prev == 1:
            self._l1 = last                                # contiguous: trust the reading (even a fault 0)
        else:
            v = self.tab.get(i - 1)                        # jump or first call: look the hour up
            self._l1 = v if v is not None else NAN
        return i

    # ------------------------------------------------------------------ predictions
    def _h0(self, i, obs):
        """(forecast for hour i, regime) regime: 'frozen' | 'fault' | 'model' | 'cold'."""
        l1 = self._l1
        h = i % 24
        if l1 == l1:
            if l1 < FAULT_KW:
                return l1, "fault"
            if h in FROZEN:
                return l1, "frozen"
            if self.model is None:
                return max(l1 + self._S(i, i - 1) - self._S(i - 1, i - 2), 0.0), "model"
            nd = obs["noves_dades_5min"]
            cont = self._prev is not None and i - self._prev == 1
            temp = float(nd.get("temp_ambient_c", NAN)) if cont else self.ttab.get(i - 1, NAN)
            irr = float(nd.get("irradiancia_wm2", NAN)) if cont else NAN
            f, s0 = self._features(i, l1, temp, irr)
            # num_threads=1: without it LightGBM spins up its thread pool on every call (spikes of 10-40 ms on a busy machine)
            d = float(self.model.predict(np.asarray([[f[c] for c in self.ci]], float), num_threads=1)[0])
            if self.base_mix:
                d += f[IDX_DSMIX]
            if self.hol_blend > 0.0 and f[IDX_LAMN] > 0.0:
                g = min(self.hol_blend * f[IDX_LAMN], 1.0)
                d += g * ((f[IDX_SGMIX] if h == 6 else f[IDX_DSMIX]) - d)
            return max(l1 + d, 0.0), "model"
        return self._S(i, i - 1), "cold"

    def _predict(self, obs, hist, H):
        i = self._sync(obs, hist)
        c = self._cache
        if c is not None and len(c[0]) >= H:
            return c
        p0, regime = self._h0(i, obs)
        out = np.empty(H)
        out[0] = p0
        if H > 1:
            known = i - 1
            S = self._S
            if self.mix:
                lam0, dref = self._lam_now(i)
            else:
                lam0, dref = 0.0, day0(i)
            rho = self.rho
            lam_d = {}

            def ref(j):
                if etype(j) != 0 or lam0 == 0.0:
                    return S(j, known)
                dj = day0(j)
                lam = lam_d.get(dj)
                if lam is None:
                    steps = sum(1 for d in range(dref + 24, dj + 1, 24) if etype(d) == 0)
                    lam = lam0 * rho ** steps
                    lam_d[dj] = lam
                swd = S(j, known, 0)
                return swd - lam * (swd - S(j, known, 2))

            a = 0.0 if regime == "fault" else p0 - ref(i)
            phi = self.phi
            f = 1.0
            prevv = p0
            for k in range(1, H):
                j = i + k
                f *= phi
                if j % 24 in FROZEN and not (k == 1 and regime in ("fault", "cold")):
                    v = prevv                                # the night repeats the 22:00 value
                else:
                    v = ref(j) + a * f
                    if v < 0.0:
                        v = 0.0
                out[k] = v
                prevv = v
        self._cache = (out, regime)
        return self._cache

    def predict_load(self, obs, hist=None, H=36):
        return self._predict(obs, hist, H)[0][:H].copy()

    def predict_load_quantiles(self, obs, hist=None, qs=(0.1, 0.25, 0.5, 0.75, 0.9)):
        out, regime = self._predict(obs, hist, 1)
        qs = np.asarray(qs, float)
        if regime in ("frozen", "fault"):
            return np.full(len(qs), out[0])
        i = self._cur
        r = self.res_cold if regime == "cold" else self.res[(i % 24, int(etype(i) > 0))]
        return np.maximum(out[0] + np.quantile(r, qs), 0.0)


